package vn.smartfarm.iot.irrigation;
import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.ObjectNode;
import java.time.*;import java.util.*;import java.util.concurrent.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.web.servlet.MockMvc;
import vn.smartfarm.iot.events.EventLog;
import static org.junit.jupiter.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"spring.datasource.url=${SMARTFARM_TEST_DB_URL}","spring.flyway.schemas=telemetry_test","spring.flyway.default-schema=telemetry_test","smartfarm.mqtt.enabled=false","smartfarm.control.enabled=false","smartfarm.irrigation.demo-enabled=false","smartfarm.irrigation.monitor-enabled=true","smartfarm.irrigation-queue.scheduling-enabled=false"})
@AutoConfigureMockMvc @EnabledIfEnvironmentVariable(named="SMARTFARM_TEST_DB_URL",matches=".+")
class CircuitValveAlertsTest {
 @Autowired CircuitValveMonitor monitor;@Autowired CircuitValveAlerts alerts;@Autowired IrrigationCircuits circuits;@Autowired JdbcTemplate jdbc;@Autowired ObjectMapper mapper;@Autowired MockMvc mvc;@Autowired EventLog events;
 Instant base;long pumps,runs,valves,queue;final UUID first=UUID.fromString("82000000-0000-4000-8000-000000000001"),second=UUID.fromString("82000000-0000-4000-8000-000000000002"),third=UUID.fromString("82000000-0000-4000-8000-000000000003");
 @BeforeEach void setup(){clean();jdbc.update("INSERT INTO irrigation_demo_binding(singleton) VALUES(1) ON CONFLICT DO NOTHING");jdbc.update("INSERT INTO iot_node(node_id,name,area_id,node_type,telemetry_version) VALUES('AWATER','Alert water','AREA001','WATER',2)");jdbc.update("INSERT INTO iot_channel(node_id,channel_id,metric,unit) VALUES('AWATER','LOW','WATER_PRESENT','boolean'),('AWATER','FLOW','FLOW_RATE','L/min')");for(int i=1;i<=2;i++){
  jdbc.update("INSERT INTO iot_node(node_id,name,area_id,node_type,telemetry_version) VALUES(?,'Alert soil','AREA001','SOIL',2)","ASOIL"+i);for(int c=1;c<=3;c++)jdbc.update("INSERT INTO iot_channel(node_id,channel_id,metric,unit) VALUES(?,?,'SOIL_MOISTURE','%')","ASOIL"+i,"SOIL"+c);
  jdbc.update("INSERT INTO irrigation_zone(zone_id,name,area_id,soil_node_id,expected_source,dry_threshold,wet_threshold) VALUES(?,'Alert zone','AREA001',?,'SIMULATOR',30,35)","AZONE"+i,"ASOIL"+i);
  circuits.create(mapper.createObjectNode().put("circuitId","ALERTC"+i).put("name","Nhánh lỗi "+i).put("zoneId","AZONE"+i).put("zoneRevision",1).put("controllerId","IRRIGATION0"+(i+3)).put("valveId","VALVE0"+(i+3)).put("pumpId","PUMP01").put("waterNodeId","AWATER").put("lowChannelId","LOW").put("flowChannelId","FLOW").put("expectedSource","SIMULATOR"));
 }base=Instant.now().minusSeconds(2);pumps=count("pump_command");runs=count("watering_run");valves=count("irrigation_demo_command");queue=count("irrigation_queue_request");}
 void clean(){jdbc.update("DELETE FROM irrigation_circuit WHERE circuit_id IN ('ALERTC1','ALERTC2')");jdbc.update("DELETE FROM irrigation_zone WHERE zone_id IN ('AZONE1','AZONE2')");jdbc.update("DELETE FROM iot_node WHERE node_id IN ('ASOIL1','ASOIL2','AWATER')");}
 @AfterEach void noDispatch(){try{assertEquals(pumps,count("pump_command"));assertEquals(runs,count("watering_run"));assertEquals(valves,count("irrigation_demo_command"));assertEquals(queue,count("irrigation_queue_request"));}finally{clean();}}
 long count(String table){return jdbc.queryForObject("SELECT COUNT(*) FROM "+table,Long.class);}
 ObjectNode packet(int i,UUID boot,int seq,String mode){long offset=boot.equals(first)?0:boot.equals(second)?100:200;var p=mapper.createObjectNode().put("schemaVersion",1).put("controllerId","IRRIGATION0"+(i+3)).put("actuatorId","VALVE0"+(i+3)).put("circuitId","ALERTC"+i).put("circuitRevision",1).put("zoneId","AZONE"+i).put("zoneRevision",1).put("bootId",boot.toString()).put("sequence",seq).put("timestamp",base.plusMillis(offset+seq).toString()).put("dataSource","SIMULATOR").put("monitorOnly",true).put("demoEnabled",false).put("gpioState","CLOSED").put("lastOrdinal",0).put("reason",mode.equals("position")?"POSITION_FAULT":mode.equals("device")?"DEVICE_FAULT":"BOOT").put("feedbackState",mode.equals("position")?"CONFLICT":"CLOSED");var f=p.putObject("positionFeedback").put("version",1).put("enabled",true).put("state",mode.equals("position")?"CONFLICT":"CLOSED");if(mode.equals("position"))f.put("fault","SWITCH_CONFLICT");else f.putNull("fault");return p;}
 void receive(int i,ObjectNode p)throws Exception{monitor.receive("smartfarm/FARM001/VALVE0"+(i+3)+"/status",mapper.writeValueAsBytes(p),false);}
 CircuitValveAlerts.Alert fault()throws Exception{receive(1,packet(1,first,0,"position"));return alerts.list().getFirst();}
 void recover()throws Exception{receive(1,packet(1,second,0,"healthy"));receive(1,packet(1,second,1,"healthy"));}
 @Test void faultOpensImmediatelyAndRepeatsDoNotRewriteEvidence()throws Exception{var a=fault();assertEquals("POSITION_FAULT",a.type());assertEquals("ALERTC1",a.circuitSnapshot().path("circuitId").asText());assertEquals("SWITCH_CONFLICT",a.openedEvidence().path("positionFeedback").path("fault").asText());receive(1,packet(1,first,1,"position"));assertEquals(1,alerts.list().size());assertEquals(a.openedEvidence(),alerts.find(a.id()).openedEvidence());assertEquals(a.openedAt(),alerts.find(a.id()).openedAt());}
 @Test void recoveryNeedsTwoAdjacentNewPacketsFromOneBoot()throws Exception{var a=fault();receive(1,packet(1,second,0,"healthy"));assertNull(alerts.find(a.id()).clearedAt());receive(1,packet(1,second,0,"healthy"));assertNull(alerts.find(a.id()).clearedAt());receive(1,packet(1,second,1,"healthy"));var done=alerts.find(a.id());assertNotNull(done.clearedAt());assertEquals(1,done.clearedEvidence().path("sequence").asInt());assertEquals(a.openedEvidence(),done.openedEvidence());}
 @Test void sequenceGapBreaksHealthyStreak()throws Exception{var a=fault();receive(1,packet(1,second,0,"healthy"));receive(1,packet(1,second,2,"healthy"));assertNull(alerts.find(a.id()).clearedAt());receive(1,packet(1,second,3,"healthy"));assertNotNull(alerts.find(a.id()).clearedAt());}
 @Test void bootSwitchBreaksHealthyStreak()throws Exception{var a=fault();receive(1,packet(1,second,0,"healthy"));receive(1,packet(1,third,0,"healthy"));assertNull(alerts.find(a.id()).clearedAt());receive(1,packet(1,third,1,"healthy"));assertNotNull(alerts.find(a.id()).clearedAt());}
 @Test void missingFeedbackDoesNotClearPositionFault()throws Exception{var a=fault();for(int i=0;i<2;i++){var p=packet(1,second,i,"healthy").put("feedbackState","UNKNOWN");p.remove("positionFeedback");receive(1,p);}assertNull(alerts.find(a.id()).clearedAt());receive(1,packet(1,second,2,"healthy"));assertNull(alerts.find(a.id()).clearedAt());receive(1,packet(1,second,3,"healthy"));assertNotNull(alerts.find(a.id()).clearedAt());}
 @Test void restartingBetweenHealthyPacketsDoesNotReusePartialProof()throws Exception{var a=fault();receive(1,packet(1,second,0,"healthy"));alerts.restart();receive(1,packet(1,second,1,"healthy"));assertNull(alerts.find(a.id()).clearedAt());receive(1,packet(1,second,2,"healthy"));assertNotNull(alerts.find(a.id()).clearedAt());}
 @Test void moreThanFifteenSecondsBetweenSamplesBreaksProof()throws Exception{base=Instant.now().minusMillis(14900);var a=fault();receive(1,packet(1,second,0,"healthy"));receive(1,packet(1,second,1,"healthy").put("timestamp",Instant.now().plusSeconds(1).toString()));assertNull(alerts.find(a.id()).clearedAt());}
 @Test void changedMappingDoesNotClearOrRetargetOldEpisode()throws Exception{var a=fault();circuits.update("ALERTC1",((ObjectNode)mapper.valueToTree(circuits.find("ALERTC1"))).put("name","New name"));assertEquals("CONFIG_CHANGED",alerts.find(a.id()).context());for(int i=0;i<2;i++)receive(1,packet(1,second,i,"healthy").put("circuitRevision",2));assertNull(alerts.find(a.id()).clearedAt());assertEquals(1,alerts.find(a.id()).circuitSnapshot().path("revision").asInt());assertEquals("ALERTC1",alerts.find(a.id()).openedEvidence().path("circuitId").asText());}
 @Test void monitorDisabledKeepsHistoryWithoutMutation()throws Exception{var a=fault();var off=new CircuitValveAlerts(jdbc,mapper,false);assertEquals("MONITOR_DISABLED",off.find(a.id()).context());assertEquals(a.openedEvidence(),off.find(a.id()).openedEvidence());assertNull(off.find(a.id()).clearedAt());}
 @Test void independentValveCannotClearAnotherValveFault()throws Exception{var a=fault();for(int i=0;i<3;i++)receive(2,packet(2,second,i,"healthy"));assertNull(alerts.find(a.id()).clearedAt());assertEquals(1,alerts.list().size());}
 @Test void deviceFaultHasSeparateEpisodeAndDoesNotRequirePositionCapabilityToRecover()throws Exception{receive(1,packet(1,first,0,"device"));var a=alerts.list().getFirst();assertEquals("DEVICE_FAULT",a.type());for(int i=0;i<2;i++){var p=packet(1,second,i,"healthy").put("feedbackState","UNKNOWN");p.remove("positionFeedback");receive(1,p);}assertNotNull(alerts.find(a.id()).clearedAt());}
 @Test void acknowledgementStoresFirstNoteWithoutClearingAndRetryIsIdempotentAfterRecovery()throws Exception{var a=fault();var ack=alerts.acknowledge(a.id(),"  Đã kiểm tra  ");assertEquals("Đã kiểm tra",ack.acknowledgementNote());assertNull(ack.clearedAt());recover();assertEquals(ack.acknowledgedAt(),alerts.acknowledge(a.id(),"Đã kiểm tra").acknowledgedAt());assertThrows(Exception.class,()->alerts.acknowledge(a.id(),"Overwrite"));}
 @Test void recoveredEpisodeRejectsFirstAcknowledgementAndOversizedNote()throws Exception{var a=fault();assertThrows(Exception.class,()->alerts.acknowledge(a.id(),"x".repeat(501)));recover();assertThrows(Exception.class,()->alerts.acknowledge(a.id(),null));assertNull(alerts.find(a.id()).acknowledgedAt());}
 @Test void concurrentDifferentNotesNeverOverwriteFirst()throws Exception{var a=fault();var start=new CountDownLatch(1);try(var pool=Executors.newFixedThreadPool(2)){var tasks=new ArrayList<Future<Boolean>>();for(String note:List.of("one","two"))tasks.add(pool.submit(()->{start.await();try{alerts.acknowledge(a.id(),note);return true;}catch(Exception e){return false;}}));start.countDown();assertNotEquals(tasks.get(0).get(5,TimeUnit.SECONDS),tasks.get(1).get(5,TimeUnit.SECONDS));}assertNotNull(alerts.find(a.id()).acknowledgedAt());assertNull(alerts.find(a.id()).clearedAt());}
 @Test void eventsHaveOwnSourceAndReceiptTimesAndCursorPagination()throws Exception{var a=fault();alerts.acknowledge(a.id(),"Seen");recover();var done=alerts.find(a.id());var from=base.minusSeconds(10);var to=Instant.now().plusSeconds(2);var page=events.list(from,to,"ALERT","VALVE04",1,null);var all=new ArrayList<EventLog.Event>();while(true){all.addAll(page.items());if(page.nextCursor()==null)break;page=events.list(from,to,"ALERT","VALVE04",1,page.nextCursor());}assertEquals(3,all.size());assertEquals(3,new HashSet<>(all.stream().map(EventLog.Event::id).toList()).size());var open=all.stream().filter(e->e.type().equals("VALVE_ALERT_OPENED")).findFirst().orElseThrow();assertEquals(a.openedAt(),open.recordedAt());assertEquals(a.openedSourceAt(),open.sourceAt());assertTrue(all.stream().allMatch(e->e.commandId()==null&&e.runId()==null));var ack=all.stream().filter(e->e.type().equals("VALVE_ALERT_ACKNOWLEDGED")).findFirst().orElseThrow();assertNull(ack.sourceAt());assertEquals(done.acknowledgedAt(),ack.eventAt());}
 @Test void httpRejectsInvalidNotesAndGetDoesNotMutateEpisodes()throws Exception{var a=fault();String api="/api/v1/valve-alerts/"+a.id();var before=jdbc.queryForObject("SELECT row_to_json(a)::text FROM circuit_valve_alert a WHERE id=?",String.class,a.id());mvc.perform(get("/api/v1/valve-alerts")).andExpect(status().isOk());mvc.perform(get(api)).andExpect(status().isOk()).andExpect(jsonPath("$.type").value("POSITION_FAULT"));assertEquals(before,jdbc.queryForObject("SELECT row_to_json(a)::text FROM circuit_valve_alert a WHERE id=?",String.class,a.id()));for(String b:List.of("{}","{\"note\":1}","{\"note\":null,\"extra\":1}","{\"note\":null,\"note\":\"x\"}","{\"note\":null}{}"))mvc.perform(put(api+"/acknowledgement").contentType("application/json").content(b)).andExpect(status().isBadRequest());mvc.perform(put(api+"/acknowledgement").contentType("application/json").content("{\"note\":\"x\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.acknowledgementNote").value("x"));mvc.perform(get("/api/v1/valve-alerts/0")).andExpect(status().isBadRequest());mvc.perform(get("/api/v1/valve-alerts/9007199254740991")).andExpect(status().isNotFound());}
 @Test void failedEpisodeInsertRollsBackTheObservationAndBootCursor()throws Exception{jdbc.execute("ALTER TABLE circuit_valve_alert ADD CONSTRAINT v28_test_reject CHECK(circuit_id<>'ALERTC1')");try{assertThrows(RuntimeException.class,()->fault());assertNull(monitor.latest("VALVE04"));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM circuit_valve_boot WHERE valve_id='VALVE04'",Integer.class));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM circuit_valve_alert_cursor WHERE circuit_id='ALERTC1'",Integer.class));}finally{jdbc.execute("ALTER TABLE circuit_valve_alert DROP CONSTRAINT v28_test_reject");}}
 @Test void fullHistoryLookupRemainsAvailableOutsideHundredRowList()throws Exception{long oldest=0;for(int i=0;i<102;i++){UUID bad=UUID.randomUUID(),good=UUID.randomUUID();receive(1,packet(1,bad,0,"position").put("timestamp",base.plusMillis(i*3).toString()));if(i==0)oldest=alerts.list().getFirst().id();receive(1,packet(1,good,0,"healthy").put("timestamp",base.plusMillis(i*3+1).toString()));receive(1,packet(1,good,1,"healthy").put("timestamp",base.plusMillis(i*3+2).toString()));}assertEquals(100,alerts.list().size());long firstId=oldest;assertTrue(alerts.list().stream().noneMatch(a->a.id()==firstId));assertNotNull(alerts.find(oldest).clearedAt());mvc.perform(get("/api/v1/valve-alerts/"+oldest)).andExpect(status().isOk());}
 @Test void nativeFeedbackPacketsOpenAndRecoverAnEpisode()throws Exception{try(var in=getClass().getResourceAsStream("/circuit-valve-alert-packets.json")){assertNotNull(in);var packets=mapper.readTree(in);long id=0;for(int i=0;i<3;i++){var p=(ObjectNode)packets.get(i);p.put("timestamp",base.plusMillis(i).toString());receive(1,p);if(i==0){id=alerts.list().getFirst().id();assertNull(alerts.find(id).clearedAt());}if(i==1)assertNull(alerts.find(id).clearedAt());}assertNotNull(alerts.find(id).clearedAt());}}
}
